export type FieldType = 'text'|'textarea'|'select'|'multiselect'|'number'|'boolean'|'json'|'url'|'datetime'|'time';
export interface Scope {tenantId:string;workspaceId:string;environment:string;userId:string}
export interface Parameter {name:string;label:string;type:FieldType;default:unknown;required:boolean;description:string;options?:string[];min?:number;max?:number;integer?:boolean;maxLength?:number;pattern?:string;typeHint?:string}
export interface Feature {id:string;label:string;route:string;group:string;description:string;roles:string[];fields:Parameter[];component:string;uiStatus:'existing_screen'|'frontend_configuration';serverStatus:'legacy_integration_unverified'|'not_connected';sourceSection:string;domains:string[];dependencies:string[];workPackageIds:string[];implementationSteps:string[];contract:null|{method:string;path:string;status:'proposed';execution:string}}
export interface WorkPackage {id:string;name:string;domain:string;gate:string;priority:string;squad:string;assignee:string;predecessors:string[];baselineStatus:string;deliveryStatus:'not_started';acceptance:string;acceptanceTestId:string;source:string;sourceRow:number;sourceIds:string;frontendFeature:string;frontendPath:string;proposedServerOwnership:string;scopeNote:string}
export interface ValidationResult {valid:boolean;errors:Record<string,string>;values:Record<string,unknown>}
export interface DraftHandoff {schema_version:'1.0';feature_id:string;status:'draft';validation:'browser_only';authorization:'server_must_resolve_scope_and_permissions';execution:'not_requested';contract_status:string;parameters:Record<string,unknown>}
